    /// A block state of the dumps' JSON (`name`, typed `states`): its name and properties.
    fn json_state(json: &serde_json::Value) -> (&str, Vec<(&str, PropertyValue<'_>)>) {
        let properties = json["states"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, typed)| {
                let (kind, v) = typed.as_object().unwrap().iter().next().unwrap();
                let value = match kind.as_str() {
                    "byte" => PropertyValue::Byte(u8::try_from(v.as_u64().unwrap()).unwrap()),
                    "int" => PropertyValue::Int(i32::try_from(v.as_i64().unwrap()).unwrap()),
                    "string" => PropertyValue::String(v.as_str().unwrap()),
                    other => panic!("property type {other}"),
                };
                (k.as_str(), value)
            })
            .collect();
        (json["name"].as_str().unwrap(), properties)
    }

    /// Every reference state reads as PMMP reads it (the dump's `deserialized.json`, which
    /// lists the states PMMP does not read as themselves): a state PMMP reads as itself is that
    /// state of the table, one PMMP reads as another state is that state's, and one PMMP rejects
    /// is the table's own state if it has one (fence connections, stair corners) and else none.
    #[test]
    fn every_reference_state_reads_as_the_state_pmmp_reads_it_as() {
        let reference: Vec<serde_json::Value> =
            serde_json::from_str(include_str!("../xtask/data/reference/blocks.json")).unwrap();
        let listed: Vec<serde_json::Value> =
            serde_json::from_str(include_str!("../xtask/data/pmmp/deserialized.json")).unwrap();
        let key = |json: &serde_json::Value| format!("{}{}", json["name"], json["states"]);
        let listed: std::collections::BTreeMap<String, &serde_json::Value> =
            listed.iter().map(|d| (key(d), &d["pmmp"])).collect();
        let (mut same, mut other, mut rejected) = (0, 0, 0);
        for r in &reference {
            let (name, properties) = json_state(r);
            let expected = match listed.get(&key(r)) {
                None => {
                    same += 1;
                    Some(State::find(name, &properties).expect("read as itself"))
                }
                Some(serde_json::Value::Null) => {
                    rejected += 1;
                    State::find(name, &properties)
                }
                Some(pmmp) => {
                    other += 1;
                    let (name, properties) = json_state(pmmp);
                    Some(State::find(name, &properties).expect("a PMMP state"))
                }
            };
            assert_eq!(State::read(name, &properties), expected, "{}", key(r));
        }
        assert_eq!((same, other, rejected), (8_963, 4_884, 10_113));
    }

    /// Every alias reads as its state with its properties in any order; changed inputs (another
    /// name, one value changed, one property left out or added) never panic, and a changed value
    /// or an added property gives `None`.
    #[test]
    fn aliases_read_in_any_order_and_changed_inputs_never_panic() {
        let pumpkin = |facing| {
            State::read(
                "minecraft:pumpkin",
                &[(
                    "minecraft:cardinal_direction",
                    PropertyValue::String(facing),
                )],
            )
        };
        let south = pumpkin("south");
        assert!(south.is_some());
        for facing in ["north", "east", "west"] {
            assert_eq!(pumpkin(facing), south, "{facing}");
        }
        assert_eq!(pumpkin("up"), None);
        assert_eq!(
            State::read(
                "minecraft:pumpkins",
                &[(
                    "minecraft:cardinal_direction",
                    PropertyValue::String("east")
                )]
            ),
            None
        );
        for a in &table::ALIASES {
            let name = table::NAMES[usize::from(a.name)];
            let mut properties: Vec<(&str, PropertyValue<'_>)> =
                properties_of(a.first_property, a.property_count)
                    .map(|p| (p.name, p.value))
                    .collect();
            properties.reverse();
            assert_eq!(
                State::read(name, &properties),
                Some(State::from_index(a.state))
            );
            for i in 0..properties.len() {
                let mut changed = properties.clone();
                changed[i].1 = match changed[i].1 {
                    PropertyValue::Byte(b) => PropertyValue::Byte(b.wrapping_add(7)),
                    PropertyValue::Int(v) => PropertyValue::Int(v.wrapping_add(1000)),
                    PropertyValue::String(_) => PropertyValue::String("no_such_value"),
                };
                assert_eq!(State::read(name, &changed), None);
                let mut fewer = properties.clone();
                fewer.remove(i);
                let _ = State::read(name, &fewer);
            }
            let mut more = properties.clone();
            more.push(("no_such_property", PropertyValue::Byte(0)));
            assert_eq!(State::read(name, &more), None);
        }
    }

    // pmmp: CopperOxidation, CopperOxidation::getNext, CopperOxidation::getPrevious
    #[test]
    fn copper_oxidation_steps_one_stage_at_a_time() {
        use CopperOxidation as O;
        let next: Vec<_> = O::ALL.iter().map(|o| o.next()).collect();
        assert_eq!(
            next,
            [
                Some(O::Exposed),
                Some(O::Weathered),
                Some(O::Oxidized),
                None
            ]
        );
        let previous: Vec<_> = O::ALL.iter().map(|o| o.previous()).collect();
        assert_eq!(
            previous,
            [None, Some(O::None), Some(O::Exposed), Some(O::Weathered)]
        );
        let prefixes = O::ALL.map(O::prefix);
        assert_eq!(prefixes, ["", "exposed_", "weathered_", "oxidized_"]);
    }

    #[test]
    fn every_copper_name_splits_and_joins_back_at_every_stage() {
        let copper: std::collections::BTreeMap<&str, State> = State::all()
            .filter(|s| s.has_trait(Trait::Copper))
            .map(|s| (s.name(), s))
            .collect();
        assert!(copper.contains_key("minecraft:copper_block"));
        for (&name, &state) in &copper {
            let (oxidation, waxed, base) = copper_parts(state).unwrap();
            assert_eq!(copper_name(oxidation, waxed, base), name);
            for oxidation in CopperOxidation::ALL {
                for waxed in [false, true] {
                    let other = copper_name(oxidation, waxed, base);
                    let parts = copper.get(other.as_str()).and_then(|&s| copper_parts(s));
                    assert_eq!(parts, Some((oxidation, waxed, base)), "{other}");
                }
            }
        }
    }

